import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/MyLibrary.css";

const MyLibrary = () => {
  const [landings, setLandings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const token = localStorage.getItem("token");
    const userInfo = JSON.parse(localStorage.getItem("userInfo") || "{}");
    const userId = userInfo?.userId;

    if (!userId || !token) {
      console.error("❌ Không tìm thấy userId hoặc token trong localStorage");
      setError("Bạn chưa đăng nhập");
      setLoading(false);
      return;
    }

    const fetchLandings = async () => {
      try {
        const baseURL = process.env.REACT_APP_API_URL || "http://localhost:5000";
        const res = await axios.get(`${baseURL}/api/landing/my/${userId}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log("✅ API trả về:", res.data);
        setLandings(res.data);
      } catch (err) {
        console.error("❌ Lỗi khi load MyLibrary:", err);
        setError("Không thể tải landing pages");
      } finally {
        setLoading(false);
      }
    };

    fetchLandings();
  }, []);

  if (loading) return <p>Đang tải...</p>;
  if (error)
    return (
      <div className="no-landing">
        <h2>Kho Landing Page của tôi</h2>
        <p>{error}</p>
      </div>
    );

  if (!landings || landings.length === 0) {
    return (
      <div className="no-landing">
        <h2>Kho Landing Page của tôi</h2>
        <p>Chưa có landing nào được lưu.</p>
      </div>
    );
  }

  return (
    <div className="mylibrary">
      <h2>Kho Landing Page của tôi</h2>
      <div className="landing-list">
        {landings.map((item) => (
          <div key={item._id} className="landing-card">
            <img
              src={item.thumbnail || "/default-thumbnail.jpg"}
              alt={item.name}
              className="thumbnail"
            />
            <h3>{item.name}</h3>
            <a
              href={item.landingPageUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              Xem landing
            </a>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MyLibrary;
